<?php
namespace App\Services\CRM;
use App\Models\{Guest,LoyaltyAccount,LoyaltyTier}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class LoyaltyService {
 public function accountFor(Guest $guest):LoyaltyAccount { return LoyaltyAccount::firstOrCreate(['property_id'=>$guest->property_id,'guest_id'=>$guest->id],['member_number'=>'LOY-'.str_pad((string)$guest->property_id,3,'0',STR_PAD_LEFT).'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,10)),'joined_at'=>today(),'loyalty_tier_id'=>LoyaltyTier::where('property_id',$guest->property_id)->where('is_active',true)->orderBy('minimum_points')->value('id')]); }
 public function add(Guest $guest,int $points,string $description='Loyalty points',mixed $source=null,?int $userId=null):LoyaltyAccount {if($points<=0)throw ValidationException::withMessages(['points'=>'Points must be greater than zero.']); return DB::transaction(function()use($guest,$points,$description,$source,$userId){if($source && \App\Models\LoyaltyTransaction::where('source_type',get_class($source))->where('source_id',$source->id)->where('type','earn')->exists())return $this->accountFor($guest);$a=$this->accountFor($guest);$a=LoyaltyAccount::whereKey($a->id)->lockForUpdate()->first();$a->points_balance+=$points;$a->lifetime_points+=$points;$this->retier($a);$a->save();$a->transactions()->create(['type'=>'earn','points'=>$points,'balance_after'=>$a->points_balance,'description'=>$description,'source_type'=>$source?get_class($source):null,'source_id'=>$source?->id,'created_by'=>$userId]);return $a->fresh('tier');});}
 public function redeem(Guest $guest,int $points,string $description='Points redemption',mixed $source=null,?int $userId=null):LoyaltyAccount {return DB::transaction(function()use($guest,$points,$description,$source,$userId){$a=$this->accountFor($guest);$a=LoyaltyAccount::whereKey($a->id)->lockForUpdate()->first();if($points<=0||$points>$a->points_balance)throw ValidationException::withMessages(['points'=>'Insufficient loyalty points.']);$a->points_balance-=$points;$a->save();$a->transactions()->create(['type'=>'redeem','points'=>-$points,'balance_after'=>$a->points_balance,'description'=>$description,'source_type'=>$source?get_class($source):null,'source_id'=>$source?->id,'created_by'=>$userId]);return $a->fresh('tier');});}
 private function retier(LoyaltyAccount $a):void {$tier=LoyaltyTier::where('property_id',$a->property_id)->where('is_active',true)->where('minimum_points','<=',$a->lifetime_points)->orderByDesc('minimum_points')->first();if($tier)$a->loyalty_tier_id=$tier->id;}
}
